using System.Diagnostics;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text.Json;
namespace LadderRecords;
[System.Runtime.Versioning.SupportedOSPlatform("windows10.0.19041")]
// 감지가 실행되는 동안 주 화면에서 기록 목록 창을 세 번 여닫으며 검사한다: 같은 창을 다시 쓰는가, 주 화면이 막히지 않는가, 미리 보기가 멈췄다가 돌아오는가,
// 바뀐 기록이 목록에 반영되는가, 화면이 굳지 않는가(화면 스레드의 가장 긴 공백 750ms 이하, 닫기 500ms 이하), 감지가 화면 스레드 밖에서 계속 실행되는가.
// 자료: 실행 파일 옆의 records.json 에 기록이 3,000개 넘게 있어야 한다(많은 기록에서의 응답을 보는 검사다). 합성 기록은 --dev-fixtures 가 만든다.
// 실행: 새 시험 폴더에 복사한 Debug 빌드에서 DJMAXLocalRecords.exe --dev-fixtures 뒤에 --records-modal-check. 10초쯤 걸린다. 결과 records-modal-validation.json
// 실제 게임 화면이 아니라 검은 그림에 RATE 글자를 그린 시험용 화면을 넣는다. 실제 캡처와 실제 인식은 검사 범위 밖이다.
static class RecordsModalChecks
{
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr w,IntPtr l);
 // 접근성 클라이언트(화면 읽기, 화면 조작 도구 등)가 이 PC 에서 듣고 있는가. 판정에는 쓰지 않고 결과에 적기만 한다(듣고 있으면 목록의 줄마다 접근성 정보를 만드느라 화면이 굳을 수 있다)
 [DllImport("UIAutomationCore.dll")]static extern bool UiaClientsAreListening();
 class Probe:MainForm{internal int Captures;internal bool CaptureOffUi=true;readonly int uiThread=Environment.CurrentManagedThreadId;public Probe(Catalog c):base(c,18770,false){}protected override SteamSnapshot ReadSteamSnapshot()=>new(true,new SteamChart("FREESTYLE","Fundamental",8,"SC"),"시험용 플레이 정보");protected override Bitmap CaptureGameFrame(IntPtr handle){Captures++;CaptureOffUi&=Environment.CurrentManagedThreadId!=uiThread;var frame=new Bitmap(1920,1080);using var graphics=Graphics.FromImage(frame);graphics.Clear(Color.Black);using var font=new Font("Arial",12,FontStyle.Bold,GraphicsUnit.Pixel);graphics.DrawString("RATE",font,Brushes.White,270,1020);graphics.DrawString("98.54%",font,Brushes.White,328,1020);return frame;}}
 public static void Run(Catalog catalog){using var main=CheckPorts.Open(18770,()=>new Probe(catalog));using var driver=new System.Windows.Forms.Timer(){Interval=150};using var heart=new System.Windows.Forms.Timer(){Interval=20};var watch=Stopwatch.StartNew();double previous=0,maxGap=0,maxGapAt=0;string stage="시작",maxGapStage="";int pulses=0,count=0;Exception? error=null;RecordsDialog? first=null;RecordsView? visibleGrid=null;var opens=new List<double>();var closes=new List<double>();bool sameInstance=true,previewSuppressed=true,updated=false;var flags=BindingFlags.NonPublic|BindingFlags.Instance;var store=(RecordStore)typeof(MainForm).GetField("store",flags)!.GetValue(main)!;
  int have=RecordRows.Read(catalog,store.Active).Count;if(have<3000)throw new CheckUnavailableException($"기록이 3,000개 넘게 있어야 하는 검사인데 실행 파일 옆의 기록은 {have}개다. 새 시험 폴더에서 --dev-fixtures 로 합성 기록을 만든 뒤 돌린다.");
  heart.Tick+=(_,_)=>{double now=watch.Elapsed.TotalMilliseconds;if(previous>0&&now-previous>maxGap){maxGap=now-previous;maxGapAt=previous;maxGapStage=stage;}previous=now;pulses++;if(visibleGrid is {Visible:true}&&visibleGrid.RowCount>0){visibleGrid.SelectIndex((pulses*3)%visibleGrid.RowCount);visibleGrid.Update();}};
  driver.Tick+=async(_,_)=>{driver.Stop();try{stage="감지 시작";var windows=(ComboBox)typeof(MainForm).GetField("windows",flags)!.GetValue(main)!;windows.Items.Add(Activator.CreateInstance(typeof(MainForm).GetNestedType("WindowItem",BindingFlags.NonPublic)!,main.Handle,"시험용 화면")!);windows.SelectedIndex=windows.Items.Count-1;typeof(MainForm).GetMethod("StartDetection",flags)!.Invoke(main,null);
   for(int pass=0;pass<3;pass++){stage=$"{pass+1}번째 열기";if(pass==1){var row=RecordRows.Read(catalog,store.Active)[0];store.SetManual(row.Chart,row.Accuracy,123456);}if(pass==2)store.Undo();var openWatch=Stopwatch.StartNew();typeof(MainForm).GetMethod("BrowseRecords",flags)!.Invoke(main,null);var dialog=(RecordsDialog)typeof(MainForm).GetField("recordsDialog",flags)!.GetValue(main)!;opens.Add(openWatch.Elapsed.TotalMilliseconds);stage=$"{pass+1}번째 열린 동안";first??=dialog;sameInstance&=ReferenceEquals(first,dialog);if(!main.Enabled||!dialog.Visible)throw new Exception("Record window blocked the main form");var grid=(RecordsView)typeof(RecordsDialog).GetField("grid",flags)!.GetValue(dialog)!;visibleGrid=grid;count=grid.RowCount;var picture=(PictureBox)typeof(MainForm).GetField("picture",flags)!.GetValue(main)!;var before=picture.Image;using(var image=new Bitmap(10,10))typeof(MainForm).GetMethod("ShowImage",flags)!.Invoke(main,new object[]{image});previewSuppressed&=ReferenceEquals(before,picture.Image);if(pass==1)updated=Enumerable.Range(0,grid.RowCount).Any(i=>grid.ItemAt(i)!.PlayCount==123456);await Task.Delay(1400);stage=$"{pass+1}번째 닫기";var closeWatch=Stopwatch.StartNew();if(pass==0)((IButtonControl)dialog.CancelButton!).PerformClick();else if(pass==1)SendMessage(dialog.Handle,0x0112,new IntPtr(0xF060),IntPtr.Zero);else dialog.Close();await Task.Yield();closes.Add(closeWatch.Elapsed.TotalMilliseconds);if(dialog.Visible||dialog.IsDisposed||!main.Enabled)throw new Exception("Close failed to hide reusable record window");visibleGrid=null;stage=$"{pass+1}번째 닫은 뒤";await Task.Delay(400);}
   var pic=(PictureBox)typeof(MainForm).GetField("picture",flags)!.GetValue(main)!;if(pic.Image?.Size!=pic.ClientSize)throw new Exception("Preview did not resume at display size");var session=(Session)typeof(MainForm).GetField("session",flags)!.GetValue(main)!;if(main.Captures<2||!main.CaptureOffUi||!session.Running)throw new Exception("Background detection did not continue");}catch(Exception e){error=e;}finally{heart.Stop();main.Close();}};
  heart.Start();driver.Start();Application.Run(main);if(error!=null)throw error;
  // 어느 기준을 벗어났는지 알 수 있게 항목별로 나눠 적는다
  var wrong=new List<string>();bool listening=false;try{listening=UiaClientsAreListening();}catch{}
  if(count<3000)wrong.Add($"목록의 기록 {count}개(3,000개 이상이어야 함)");if(pulses<20)wrong.Add($"화면 스레드가 돈 횟수 {pulses}(20 이상이어야 함)");if(maxGap>750)wrong.Add($"화면 스레드의 가장 긴 공백 {maxGap:F1}ms(750ms 이하여야 함)");
  if(!sameInstance)wrong.Add("창을 다시 열 때 같은 창을 쓰지 않음");if(!previewSuppressed)wrong.Add("창이 열린 동안 미리 보기가 멈추지 않음");if(!updated)wrong.Add("바뀐 기록이 목록에 반영되지 않음");if(closes.Any(t=>t>500))wrong.Add($"닫기 {closes.Max():F1}ms(500ms 이하여야 함)");
  File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"records-modal-validation.json"),JsonSerializer.Serialize(new{passed=wrong.Count==0,wrong,accessibility_clients_listening=listening,records=count,pulses,max_ui_gap_ms=maxGap,max_ui_gap_at_ms=maxGapAt,max_ui_gap_during=maxGapStage,open_times_ms=opens,close_to_next_ui_turn_ms=closes,reused_same_dialog=sameInstance,main_window_remains_enabled=true,close_button_and_titlebar_x_tested=true,preview_suppressed_while_open=previewSuppressed,preview_resumed=true,changed_record_refreshed=updated,screen_detection_running=true,screen_captures=main.Captures,capture_off_ui_thread=main.CaptureOffUi,scrolling_during_detection=true},new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));
  if(wrong.Count>0)throw new Exception("기록 창 검사 실패: "+string.Join(", ",wrong)+$" · 가장 긴 공백은 {maxGapStage}({maxGapAt:F0}ms 부터) · 접근성 클라이언트가 듣는 중: {(listening?"예":"아니요")}");
 }
}
